// Open transfer ladle and cast slag pot; geometry stays in the cutaway's 900×650 space.
export function factoryLadleDefs(){return `<linearGradient id="ladle-shell" x1="0" y1=".2" x2="1" y2=".7"><stop stop-color="#283c40"/><stop offset=".17" stop-color="#566e70"/><stop offset=".34" stop-color="#81918a"/><stop offset=".49" stop-color="#465b5a"/><stop offset=".8" stop-color="#304347"/><stop offset="1" stop-color="#1d3034"/></linearGradient><linearGradient id="ladle-band"><stop stop-color="#1a3036"/><stop offset=".23" stop-color="#b3b8a3"/><stop offset=".45" stop-color="#81918a"/><stop offset=".76" stop-color="#4a6566"/><stop offset="1" stop-color="#172d34"/></linearGradient><linearGradient id="ladle-rim" x2="0" y2="1"><stop stop-color="#c3c6ad"/><stop offset=".4" stop-color="#697e78"/><stop offset="1" stop-color="#263d41"/></linearGradient><radialGradient id="ladle-cavity" cx=".44" cy=".25" r=".8"><stop stop-color="#414742"/><stop offset=".55" stop-color="#202d2b"/><stop offset="1" stop-color="#101f23"/></radialGradient><linearGradient id="ladle-lining" x2="0" y2="1"><stop stop-color="#c1af88"/><stop offset=".35" stop-color="#8d7860"/><stop offset="1" stop-color="#5b4f40"/></linearGradient><linearGradient id="slag-cast-shell"><stop stop-color="#334748"/><stop offset=".25" stop-color="#708077"/><stop offset=".5" stop-color="#53635d"/><stop offset="1" stop-color="#223839"/></linearGradient><pattern id="ladle-scale" width="17" height="13" patternUnits="userSpaceOnUse"><path d="M1 3h3m6 5h4M6 12h2" stroke="#d1c6a4" stroke-width=".55" opacity=".2"/><path d="M8 1h4M1 9h2" stroke="#142c30" stroke-width=".8" opacity=".3"/><circle cx="5" cy="6" r=".7" fill="#997c52" opacity=".28"/></pattern>`;}
function trunnions(rx,y){return [-1,1].map(side=>`<g transform="translate(${side*(rx-4)} ${y}) scale(${side} 1)"><path d="M-1 -12L10 -10 13 12 -3 14Z" fill="#34494b" stroke="#81928a" stroke-width="1.2"/><path d="M5 -7H20V8H5Z" fill="url(#ladle-band)" stroke="#263b3d" stroke-width="1.2"/><ellipse cx="20" cy=".5" rx="4" ry="7.5" fill="#5d7470" stroke="#a6b1a0" stroke-width="1.1"/><ellipse cx="21" cy=".5" rx="1.5" ry="3.4" fill="#263c3e"/><path d="M0 -8L1 9" stroke="#c0c3aa" stroke-width=".8" opacity=".65"/></g>`).join('');}
function liningJoints(rx,ry){return Array.from({length:14},(_,i)=>{const a=i*Math.PI/7;return `<path d="M${(Math.cos(a)*rx).toFixed(2)} ${(Math.sin(a)*ry).toFixed(2)}L${(Math.cos(a)*(rx-7)).toFixed(2)} ${(Math.sin(a)*(ry-3)).toFixed(2)}" stroke="#4e4539" stroke-width=".8" opacity=".65"/>`;}).join('');}
export function factoryReceivers(){return `<g class="factory-slag-receiver" transform="translate(640 505)"><ellipse cy="49" rx="56" ry="6" fill="#354d40" opacity=".16"/><path d="M-31 39L-35 46H35L31 39Z" fill="#2b4141" stroke="#76877c" stroke-width="1.5"/>${trunnions(47,17)}<path d="M-50 0Q-49 25 -34 37Q0 49 34 37Q49 25 50 0Z" fill="url(#slag-cast-shell)" stroke="#273f40" stroke-width="2"/><path d="M-50 0Q-49 25 -34 37Q0 49 34 37Q49 25 50 0Z" fill="url(#ladle-scale)"/><path d="M-43 7Q-39 28 -28 39M-20 11L-16 43M20 11L16 43M43 7Q39 28 28 39" fill="none" stroke="#1c3437" stroke-width="4.8"/><path d="M-44 7Q-40 27 -29 38M-21 11L-17 42M19 11L15 42M42 7Q38 27 27 38" fill="none" stroke="#9ba590" stroke-width="1.1" opacity=".65"/><path d="M-43 25Q0 44 43 25" fill="none" stroke="#b1b8a1" stroke-width="1.2"/><path d="M-28 16l10 3 7 11-13 -2Z M25 15l10 2-4 13-9 -4Z" fill="#8e7050" opacity=".26"/><ellipse rx="52" ry="12" fill="url(#ladle-rim)" stroke="#a8b3a2" stroke-width="1.5"/><ellipse cy="1" rx="46" ry="8.8" fill="#655f4c" stroke="#ad9b78" stroke-width="1.1"/><ellipse cy="2" rx="43" ry="6.9" fill="url(#ladle-cavity)"/><ellipse class="factory-slag-pool" cy="2" rx="42" ry="6.3" fill="url(#slag-liquid)"/><path d="M-50 2Q0 23 50 2" fill="none" stroke="#d3ccb1" stroke-width="1.2" opacity=".65"/><path d="M-31 -9l12 2m21 -3 11 2m25 4 7 2" stroke="#62523d" stroke-width="1.5" opacity=".7"/></g>
 <g class="factory-iron-receiver" transform="translate(800 565)"><ellipse cy="78" rx="82" ry="8" fill="#354d40" opacity=".16"/><path d="M-49 64L-56 73V78H56V73L49 64Z" fill="#20383d" stroke="#84958a" stroke-width="1.3"/><path d="M-54 75H54" stroke="#aeb6a0" stroke-width="1.3"/>${trunnions(66,23)}<path d="M-69 0L-58 65Q0 80 58 65L69 0Z" fill="url(#ladle-shell)" stroke="#233b3e" stroke-width="2"/><path d="M-69 0L-58 65Q0 80 58 65L69 0Z" fill="url(#ladle-scale)"/><path d="M-59 8L-50 65Q0 77 50 65" fill="none" stroke="#162f33" stroke-width="1.7" opacity=".55"/>
 <g fill="none">${[-43,-17,17,43].map(x=>`<path d="M${x} 8L${x*.85} 69" stroke="#1a3034" stroke-width="3.5"/><path d="M${x-1.2} 8L${x*.85-1.2} 68" stroke="#a6b0a1" stroke-width=".9" opacity=".65"/>`).join('')}<path d="M-65 23Q0 47 65 23" stroke="#1b3035" stroke-width="9"/><path d="M-65 21Q0 45 65 21" stroke="url(#ladle-band)" stroke-width="6"/><path d="M-62 47Q0 67 62 47" stroke="#1b3035" stroke-width="8"/><path d="M-62 45Q0 65 62 45" stroke="url(#ladle-band)" stroke-width="5"/><path d="M-65 19Q0 43 65 19M-62 43Q0 63 62 43" stroke="#c2c6af" stroke-width=".8" opacity=".7"/></g>
 ${[-53,-32,0,32,53].map(x=>{const y=23+(1-(x/65)**2)*11;return `<circle cx="${x}" cy="${y.toFixed(2)}" r="1.35" fill="#b3b9a3" stroke="#253e41" stroke-width=".7"/>`;}).join('')}<path d="M-52 10l12 -2 6 13-14 -4Z M27 12l19 1-6 11-11 -2Z M-21 50l10 2 5 12-13 -3Z" fill="#aa8156" opacity=".24"/><path d="M-46 52l7 2m7 -7 5 1m30 15 9 1m18 -29 7 1" stroke="#b8b6a0" stroke-width=".8" opacity=".4"/>
 <ellipse rx="73" ry="15" fill="url(#ladle-rim)" stroke="#b0b9a4" stroke-width="1.6"/><ellipse cy=".3" rx="66" ry="11.6" fill="url(#ladle-lining)" stroke="#514c40" stroke-width="1.3"/>${liningJoints(65,11)}<ellipse cy="2" rx="58.5" ry="8.2" fill="url(#ladle-cavity)"/><ellipse class="factory-iron-pool" cy="2" rx="57" ry="7.6" fill="url(#iron-liquid)"/><path d="M-72 2Q0 31 72 2" fill="none" stroke="#192f34" stroke-width="2.4"/><path d="M-70 2Q0 28 70 2" fill="none" stroke="#c1c4ab" stroke-width="1.2" opacity=".85"/><path d="M-48 -10l15 2m29 -5 12 1m33 4 12 2" stroke="#564e40" stroke-width="1.4" opacity=".7"/></g>`;}
